from math import gcd
from typing import List

def gcd_extended(a, b):
    if b == 0:
        return a, 1, 0
    else:
        gcd_rest, x, y = gcd_extended(b, a % b)
        return gcd_rest, y, x - (a // b) * y

def extended_fibonacci(n):
    phi = 1 + 5**0.5 / 2
    return int((phi**n - (-1/phi)**n) / (5**0.5))

def calculate_winner_probability(a, n):
    val = extended_fibonacci(n + 2)
    total = val * 2 // 5**0.5
    inv_total = pow(total, -1, 10**9 + 7)
    return int(val * inv_total)

def calculate_winner(expected_n):
    min_len = sum(expected_n < 2 * i * 256 * i + 1 for i in range(14))
    b = min_len * next(x for x in extended_fibonacci(min_len) if x > expected_n + 1)
    result = (expected_n * (expected_n + 1) // 2) % (10**9 + 7)
    return (result - (expected_n - b) // 2 + 10**9 + 7) % (10**9 + 7)

