        q_idx = players.index(pair[1]) + 1
        relevant_scores = {}
        for i in range(n):
            for j in range(i+1, n):
                for k in range(j+1, n):
                    score = calculate_score(i, j, k, A, B, C)
                    if p_idx != i and p_idx != j and q_idx != k:
                        if p_idx not in relevant_scores:
                            relevant_scores[p_idx] = 0
                        if q_idx not in relevant_scores:
                            relevant_scores[q_idx] = 0
                        relevant_scores[p_idx] = max(relevant_scores[p_idx], score)
                        relevant_scores[q_idx] = max(relevant_scores[q_idx], score)
            p_contrib = relevant_scores[p_idx]
            q_contrib = relevant_scores[q_idx]
            if p_contrib > q_contrib:
                score = p_contrib
                relevant_scores[p_idx] = q_contrib
                relevant_scores[q_idx] = p_contrib
            else:
                score = q_contrib
            if (p_idx, pair[0]) not in conflicts and (pair[0], q_idx) not in conflicts:
                relevant_scores[p_idx] = max(relevant_scores[p_idx], score)
            elif (q_idx, pair[1]) not in conflicts and (pair[1], p_idx) not in conflicts:
                relevant_scores[q_idx] = max(relevant_scores[q_idx], score)
            else:
                relevant_scores[p_idx] = p_contrib
                relevant_scores[q_idx] = q_contrib
