def find_minimal_k_covering(U, V, E, minDegree):
    if len(E) * 2 / (2 * len(U)) < minDegree:
        return len(E)*2, tuple(range(1, len(E)+1))
    covered = set()
    total_covered = 0
    used_edges = set()

    while total_covered < len(U):
        for edge in E:
            if edge not in used_edges and (edge[0] in covered or edge[1] in covered):
                covered.add(edge)
                total_covered += 1
                if total_covered >= len(U):
                    return len(E)*2, [edge for edge in E if edge in covered]
                used_edges.add(edge)
                if edge[0] in covered and edge[1] in covered:
                    break
        else:
            if total_covered >= len(U):
                return len(E)*2, [edge for edge in E if edge in covered]
            return 0, []

    return 0, []

