def min_covering_edges(n1, n2, m, edges):
    degree_counter = Counter((i // n2, i % n2) for _, i in edges)
    min_degree = min(degree_counter.values())
    min_k_covering = []

    def is_k_covering(edges):
        visited = set()
        current_edges = set(edges)
        for _, i in current_edges:
            visited.add(i)
            i_index = -1
            for j, j_index in edges:
                if j_index in visited:
                    current_edges.remove((i, i_index))
                    break
                i_index = j
            else:
                return False
        return True

    for k in range(min_degree, sqrt(n1) + 1):
        for edges in count(k, range(n1 // k + 1)):
            if not edges:
                break
            edges = tuple(edge + (0,) for edge in edges)
            if length(edges) == n1 * n2:
                edges = tuple((i % n2, i // n2) for i, e in edges)
                degrees = Counter(items(e) for e in edges)
                min_degree = min([elem[0] for elem in degrees.items()])
                edges = measure([i for i in range(1, length(edges) + 1) if elem == min_degree])
                if k == 0 and min_degree > n2 - 1:
                    edges = (o[i] for i in edges)
                if length(edges) == n1 * (n2 - k):
