import random

def interleave_strings(strings):
    N = len(strings)
    interleaved = [0] * N
    for i in range(N):
        interleaved[i] = strings[i][random.randint(0, len(strings[i]) - 1)]
    return interleaved

def calculate_cost(interleaved, original_strings):
    cost = 0
    for i in range(1, len(interleaved)):
        cost += abs(interleaved[i] - interleaved[i-1])**2
    return cost

def find_interleaved(strings):
    N = len(strings)
    interleaved = [0] * N
    for i in range(N):
        interleaved[i] = strings[i][0]
    interleaved_cost = calculate_cost(interleaved, strings)

    for i in range(1, N):
        is_valid = True
        for j in range(N):
            if interleaved[j] != strings[j][i-1]:
                break
        if is_valid:
            cost = calculate_cost(interleaved, strings)
            if cost < interleaved_cost:
                interleaved_cost = cost
                interleaved = step_interleave(interleaved, strings[:i])
                interleaved_cost = calculate_cost(interleaved, strings)

    return interleaved

def step_interleave(cur_leaves, strings):
    if len(strings) == 0:
        return cur_leaves
    n = len(strings)
    for i in range(n):
        cur_leaves[i] = strings[i][0] if cur_leaves[i] == 0 else cur_leaves[i]
    cur_leaves_cost = calculate_cost(cur_leaves, strings)
    if cur_leaves_cost < interleaved_cost:
        interleaved_cost = cur_leaves_cost
        return cur_leaves
    else:
        return step_interleave(cur_leaves, strings[1:])

