# Compute the binomial coefficient modulo MOD
def mod_binom(n, k):
    if k < 0 or k > n:
        return 0
    result = 1
    for i in range(k):
        result = (result * (n - i)) % MOD
        result = (result * mod_inv(i + 1)) % MOD
    return result

# Function to compute the modular inverse
def mod_inv(x):
    return pow(x, MOD - 2, MOD)

# Compute the probability of winning given a_i and a_j
def prob_win(a_i, a_j):
    return a_i / (a_i + a_j)

# Compute the expected number of winners
def expected_winners(n, a):
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(n):
        for j in range(i):
            dp[i + 1] = (dp[i + 1] + dp[j] * (1 - prob_win(a[i], a[j]) - prob_win(a[i], a[j])) * prob_win(a[j], a[i + 1]) / (1 - prob_win(a[j], a[i + 1]))) % MOD
    return dp[n]

